#!/usr/bin/env python3
"""LT-6.4 (FB-101): large-upload handling — 20 MB image generated by script.

The item's three claims, measured on a real server (fresh data dir):

1. **Friendly size error.** The 20 MB image is refused on every UI upload entry
   point — editor inspector (``#photoUpload``: "under 15 MB" alert), editor
   asset browser (``EInviteAssetWorkflow``: "Choose an image under 15 MB"
   toast), materials page (``#uploadFile`` + ``#uploadBtn``: "exceeds the 15 MB
   limit" alert) — with **no** upload request fired and the main thread not
   frozen while refusing.
2. **Compress/resize on upload.** A large-but-allowed image (~17.5 MP, under
   the 15 MB client limit, max side 5000 > 2200) goes through
   ``optimizeImageFile``: the stored asset is a WebP whose bytes are strictly
   below the source size and whose width/height are clamped to <= 2200.
3. **No editor freeze.** Long tasks (``PerformanceObserver('longtask')``) and
   requestAnimationFrame gaps are recorded across both flows; the test asserts
   a bound instead of assuming one, and prints the measured maxima.

Server side of the guard: a direct 20 MB raw POST to
``/api/invitations/<id>/assets/raw`` returns HTTP 400 ``Material exceeds 15 MB``.

Screenshots are written when ``EINVITE_CAPTURE_DIR`` is set.
"""
from __future__ import annotations

import os
import time
from pathlib import Path

import pytest

from browser_runtime import dismiss_editor_onboarding, launch_chromium

ROOT = Path(__file__).resolve().parents[1]
SLUG = "lt-6-4-large-upload"
PASSWORD = "Strong-lt-6-4-pass-123"

# "No editor freeze" bounds: far above any single legitimate downscale step, far
# below a visible freeze. Measured maxima are printed for the item notes.
MAX_LONG_TASK_MS = 1000
MAX_RAF_GAP_MS = 1500

_INSTALL = """() => {
  window.__lt64 = {tasks: [], gap: 0, last: performance.now()};
  try {
    new PerformanceObserver((list) => {
      for (const entry of list.getEntries()) window.__lt64.tasks.push(Math.round(entry.duration));
    }).observe({entryTypes: ['longtask']});
  } catch (error) {}
  const tick = (now) => {
    const gap = now - window.__lt64.last;
    if (gap > window.__lt64.gap) window.__lt64.gap = gap;
    window.__lt64.last = now;
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}"""

_RESET = "() => { window.__lt64.tasks = []; window.__lt64.gap = 0; window.__lt64.last = performance.now(); }"
_READ = "() => ({tasks: window.__lt64.tasks.slice(), gap: window.__lt64.gap})"

_CSRF_HEADERS = """() => {
    const match = document.cookie.match(/(?:^|;\\s*)einvite_csrf=([^;]*)/);
    return match ? {'X-CSRF-Token': decodeURIComponent(match[1])} : {};
}"""


def _document() -> dict:
    return {
        "schemaVersion": 13,
        "eventType": "Wedding",
        "fields": {
            "names": "Sophea & Dara",
            "namesKm": "",
            "date": "2029-12-27",
            "time": "16:05",
            "venue": "Phnom Penh",
            "venueKm": "",
            "message": "Welcome",
            "messageKm": "",
        },
        "settings": {
            "rsvpEnabled": True,
            "wishesEnabled": False,
            "scheduleEnabled": False,
            "venueEnabled": False,
            "galleryEnabled": False,
            "countdownEnabled": False,
            "musicEnabled": False,
            "openingEnabled": True,
            "contactEnabled": False,
        },
        "languageMode": "en",
        "dateFormat": "gregorian",
        "accent": "#9d4555",
        "palette": {"background": "#fff8f2", "surface": "#ffffff", "text": "#342c26", "heading": "#9d4555"},
        "sectionOrder": ["rsvp"],
        "schedule": [],
        "venues": [],
        "customBlocks": [],
        "designPages": [],
        "objects": {},
        "slug": SLUG,
    }


def _write_big_png(path: Path, side: int = 2700) -> None:
    """Noise PNG written at compress_level=0: ~side*side*3 bytes, >= 20 MB for side=2700."""
    from PIL import Image

    raw = os.urandom(side * side * 3)
    Image.frombytes("RGB", (side, side), raw).save(path, "PNG", compress_level=0)


def _write_large_jpeg(path: Path, width: int = 5000, height: int = 3500) -> None:
    """17.5 MP noise JPEG under the 15 MB client limit (quality loop keeps it there)."""
    from PIL import Image

    raw = os.urandom(width * height * 3)
    image = Image.frombytes("RGB", (width, height), raw)
    for quality in (60, 50, 45, 40, 35):
        image.save(path, "JPEG", quality=quality)
        if path.stat().st_size < 14_500_000:
            return
    raise AssertionError(f"could not encode {path.name} under 14.5 MB")


def _responsive(page, label: str, *, max_task: int = MAX_LONG_TASK_MS, max_gap: int = MAX_RAF_GAP_MS):
    metrics = page.evaluate(_READ)
    worst = max(metrics["tasks"], default=0)
    print(f"[{label}] longTasks={len(metrics['tasks'])} worst={worst}ms rAFgap={metrics['gap']:.1f}ms", flush=True)
    assert worst <= max_task, (label, metrics)
    assert metrics["gap"] <= max_gap, (label, metrics)
    return worst, metrics["gap"]


def _wait_asset(page, base: str, invite_id: str, predicate, timeout: float = 40.0):
    deadline = time.time() + timeout
    assets = []
    while time.time() < deadline:
        response = page.request.get(base + "/api/assets")
        if response.ok:
            assets = response.json()
            found = [asset for asset in assets if predicate(asset)]
            if found:
                return found[0], assets
        page.wait_for_timeout(400)
    return None, assets


def test_large_upload_handling():
    sync_playwright = pytest.importorskip("playwright.sync_api")
    from v14_test_utils import app_server

    capture = Path(os.environ["EINVITE_CAPTURE_DIR"]) if os.environ.get("EINVITE_CAPTURE_DIR") else None
    if capture:
        capture.mkdir(parents=True, exist_ok=True)

    errors: list[str] = []
    with app_server() as (_process, base, data):
        big20 = data / "lt64-big-20mb.png"
        _write_big_png(big20)
        big_bytes = big20.stat().st_size
        assert big_bytes >= 20_000_000, big_bytes

        large_ok = data / "lt64-large-ok.jpg"
        _write_large_jpeg(large_ok)
        ok_bytes = large_ok.stat().st_size
        assert 1_500_000 < ok_bytes < 15_000_000, ok_bytes

        with sync_playwright.sync_playwright() as play:
            try:
                browser = launch_chromium(play)
            except Exception as exc:  # pragma: no cover - environment dependent
                pytest.skip(f"Chromium unavailable: {exc}")

            context = browser.new_context(viewport={"width": 1440, "height": 900})
            page = context.new_page()
            page.on("pageerror", lambda error: errors.append(str(error)))
            requests: list[tuple[str, str]] = []
            page.on("request", lambda request: requests.append((request.method, request.url)))
            dialogs: list[str] = []
            page.on("dialog", lambda dialog: (dialogs.append(dialog.message), dialog.dismiss()))
            # ``ui-dialogs.js`` replaces ``window.alert`` with the themed toast
            # stack, so the friendly messages are asserted as toast text.

            page.goto(base + "/dashboard.html", wait_until="domcontentloaded", timeout=30000)
            page.locator("#authRegisterTab").click()
            page.locator("#email").fill("lt-6-4-upload@example.com")
            page.locator("#password").fill(PASSWORD)
            page.locator("#registerConfirmPassword").fill(PASSWORD)
            page.locator("#loginBtn").click()
            page.wait_for_selector("#dashboardView:not([hidden])", timeout=20000)

            created = page.evaluate(
                """async ([documentModel, token]) => {
                    const response = await fetch('/api/invitations', {
                        method: 'POST', headers: {'Content-Type': 'application/json', ...token},
                        body: JSON.stringify({slug: documentModel.slug, document: documentModel})
                    });
                    if (!response.ok) throw Error(await response.text());
                    return response.json();
                }""",
                [_document(), page.evaluate(_CSRF_HEADERS)],
            )
            invite_id = created["id"]
            editor_url = base + f"/invitations/{invite_id}/editor"

            page.goto(editor_url, wait_until="domcontentloaded", timeout=30000)
            page.wait_for_function("() => document.documentElement.dataset.editorReady === 'true'", timeout=30000)
            dismiss_editor_onboarding(page)
            page.evaluate(_INSTALL)

            def upload_requests() -> list[tuple[str, str]]:
                # Writes only: the asset browser's own listing refresh is a GET.
                return [
                    (method, url) for method, url in requests
                    if method in ("POST", "PUT", "PATCH") and ("/assets" in url or "/uploads" in url)
                ]

            # 1) Editor inspector path — 20 MB must be refused before any work.
            requests.clear()
            dialogs.clear()
            page.evaluate(_RESET)
            page.set_input_files("#photoUpload", str(big20))
            page.wait_for_selector("text=Please choose an image under 15 MB", timeout=6000)
            assert upload_requests() == [], upload_requests()
            worst_a, gap_a = _responsive(page, "inspector-20mb-refusal")
            if capture:
                page.screenshot(path=str(capture / "lt-6-4-inspector-refusal.png"))

            # 2) Asset browser path — the toast, not an alert.
            requests.clear()
            page.evaluate("() => window.EInviteAssetWorkflow.open()")
            page.wait_for_selector("#v23AssetBrowser[open]", timeout=10000)
            page.set_input_files("#v23AssetBrowser input[data-file]", str(big20))
            page.wait_for_selector("text=Choose an image under 15 MB", timeout=8000)
            assert upload_requests() == [], upload_requests()
            worst_b, gap_b = _responsive(page, "asset-browser-20mb-refusal")
            if capture:
                page.screenshot(path=str(capture / "lt-6-4-asset-browser-refusal.png"))
            page.evaluate("() => document.querySelector('#v23AssetBrowser')?.close()")

            # 3) Materials page path — alert names the file and the limit; no request.
            page.goto(base + "/materials.html", wait_until="domcontentloaded", timeout=30000)
            page.wait_for_function("() => document.querySelectorAll('#uploadInvitation option').length > 0", timeout=20000)
            page.locator("button.material-upload-toggle").click()  # FB-44: box ships hidden
            page.wait_for_selector("#uploadInvitation", state="visible", timeout=8000)
            page.select_option("#uploadInvitation", invite_id)
            page.evaluate(_INSTALL)
            page.evaluate(_RESET)
            requests.clear()
            dialogs.clear()
            page.set_input_files("#uploadFile", str(big20))
            page.click("#uploadBtn")
            page.wait_for_selector("text=exceeds the 15 MB limit", timeout=6000)
            assert upload_requests() == [], upload_requests()
            worst_c, gap_c = _responsive(page, "materials-20mb-refusal")
            if capture:
                page.screenshot(path=str(capture / "lt-6-4-materials-refusal.png"))

            # 4) Allowed large image: optimize -> resize/compress -> store.
            page.goto(editor_url, wait_until="domcontentloaded", timeout=30000)
            page.wait_for_function("() => document.documentElement.dataset.editorReady === 'true'", timeout=30000)
            dismiss_editor_onboarding(page)
            page.evaluate(_INSTALL)
            page.evaluate(_RESET)
            page.set_input_files("#photoUpload", str(large_ok))
            stored, assets = _wait_asset(
                page, base, invite_id,
                lambda asset: asset.get("invitationId") == invite_id
                and str(asset.get("mime") or "").startswith("image/webp"),
            )
            worst_d, gap_d = _responsive(page, "large-image-optimize-upload")
            assert stored, [asset.get("name") for asset in assets]
            assert stored["name"].endswith(".webp"), stored
            assert stored["size"] < ok_bytes, (stored["size"], ok_bytes)
            assert 0 < stored["width"] <= 2200 and 0 < stored["height"] <= 2200, (stored["width"], stored["height"])
            print(
                f"[large-image] source={ok_bytes}B 5000x3500 -> stored={stored['size']}B "
                f"{stored['width']}x{stored['height']}",
                flush=True,
            )
            if capture:
                page.screenshot(path=str(capture / "lt-6-4-large-uploaded.png"))

            # 5) Server side of the guard: the raw route refuses the 20 MB body.
            token = page.evaluate(_CSRF_HEADERS)
            response = page.request.post(
                base + f"/api/invitations/{invite_id}/assets/raw",
                headers={"Content-Type": "image/png", "X-File-Name": "lt64-big-20mb.png", **token},
                data=big20.read_bytes(),
            )
            assert response.status == 400, (response.status, response.text()[:200])
            payload = response.json()
            assert "exceeds 15 MB" in str(payload.get("error", "")), payload

            assert errors == [], errors
            assert dialogs == [], dialogs  # window.alert is themed; native dialogs would be a defect
            context.close()
            browser.close()

        print(
            "LT_6_4_UPLOAD_PROBE_PASSED "
            f"big={big_bytes}B allowed={ok_bytes}B "
            f"maxLongTask={max(worst_a, worst_b, worst_c, worst_d)}ms "
            f"maxGap={max(gap_a, gap_b, gap_c, gap_d):.1f}ms",
            flush=True,
        )
